// Valida la forma de la entrada del router. El archivo en sí se valida contra Telegram en el paso siguiente
const i = $input.first().json;
const chatId = String(i.chat_id ?? '').trim();
if (!/^-?\d{1,20}$/.test(chatId)) throw new Error('validation: chat_id no es numérico');
const fileId = String(i.file_id ?? '').trim();
if (!/^[A-Za-z0-9_-]{8,256}$/.test(fileId)) throw new Error('validation: file_id con formato inválido');
const mediaKind = String(i.media_kind ?? '');
if (!['image', 'video'].includes(mediaKind)) throw new Error('validation: media_kind debe ser image o video');
const messageId = Number.isSafeInteger(Number(i.message_id)) ? Number(i.message_id) : 0;
return [{ json: { chat_id: chatId, file_id: fileId, media_kind: mediaKind, caption: String(i.caption ?? '').trim().slice(0, 1024), message_id: messageId,
  update_id: Number(i.update_id) || 0, started_at: new Date().toISOString() } }];

// Pide la ruta del archivo a Telegram. La URL de descarga se arma con el host fijo api.telegram.org (OWASP A10); aquí no se descarga nada
const e = $('Validar entrada').first().json;
const MB = 1024 * 1024;
const reject = (reason) => [{ json: { ...e, accepted: false, reason } }];
const r = await this.helpers.httpRequest({ method: 'GET', url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/getFile`,
  qs: { file_id: e.file_id }, json: true, ignoreHttpStatusErrors: true, timeout: 30000 });
if (!r?.ok) {
  const d = String(r?.description ?? '');
  if (/too big/i.test(d)) return reject('❌ El archivo pesa más de 20 MB y Telegram no deja que el bot lo descargue. Por favor comprímelo y envíalo de nuevo.');
  if (/wrong file_id|invalid/i.test(d)) return reject('❌ No pude leer ese archivo. Envíalo de nuevo como foto.');
  throw new Error(`telegram_http: getFile respondió ${r?.error_code ?? 'sin código'}`);
}
const filePath = String(r.result?.file_path ?? '');
if (!/^[A-Za-z0-9_\/.-]+$/.test(filePath) || filePath.includes('..')) throw new Error('telegram_http: file_path con formato inesperado');
const ext = (filePath.split('.').pop() || '').toLowerCase();
const okExt = e.media_kind === 'image' ? ['jpg', 'jpeg', 'png', 'webp'] : ['mp4', 'mov'];
if (!okExt.includes(ext)) return reject(e.media_kind === 'image' ? '❌ Formato no soportado. Solo acepto imágenes JPG, PNG o WebP, o videos MP4 y MOV.' : '❌ Formato de video no soportado. Solo acepto MP4 y MOV.');
if (Number(r.result?.file_size ?? 0) > 20 * MB) return reject('❌ El archivo supera 20 MB. Por favor comprímelo antes de enviarlo.');
return [{ json: { ...e, accepted: true, file_path: filePath, image_url: e.media_kind === 'image' ? `https://api.telegram.org/file/bot${$env.TELEGRAM_BOT_TOKEN}/${filePath}` : null } }];

const tg = (method, body) => this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/${method}`, body, json: true, timeout: 30000 });
// El archivo no cumple: se le dice al remitente por qué y no se crea nada. Si el aviso falla no se convierte en error del flujo
const e = $input.first().json;
let notified = true;
try { await tg('sendMessage', { chat_id: e.chat_id, text: e.reason, ...(e.message_id ? { reply_to_message_id: e.message_id, allow_sending_without_reply: true } : {}) }); } catch (err) { notified = false; }
return [{ json: { ok: false, rejected: true, reason: e.reason, notified } }];

// Crea el content_item y deja la fila del paso 'ingest' en pipeline_steps. En la base va la referencia al archivo (telegram:<file_id>), nunca una URL con el token del bot
const e = $input.first().json;
const base = `${$env.SUPABASE_URL}/rest/v1`;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json', Prefer: 'return=representation' };
const created = await this.helpers.httpRequest({ method: 'POST', url: `${base}/content_items`, headers, json: true, timeout: 30000,
  body: { asset_type: e.media_kind, raw_asset_url: `telegram:${e.file_id}`, status: 'ingested', notes: e.caption || null } });
const id = (Array.isArray(created) ? created[0] : created)?.id;
if (!id) throw new Error('supabase: content_items no devolvió el id');
await this.helpers.httpRequest({ method: 'POST', url: `${base}/pipeline_steps`, headers, json: true, timeout: 30000,
  body: { content_item_id: id, step: 'ingest', attempt: 1, status: 'succeeded', started_at: e.started_at, finished_at: new Date().toISOString(), n8n_execution_id: String($execution.id) } });
return [{ json: { ...e, content_item_id: id } }];

const tg = (method, body) => this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/${method}`, body, json: true, timeout: 30000 });
// Avisa al remitente que el archivo llegó. Si el aviso falla, la ingesta sigue
const e = $input.first().json;
const text = e.media_kind === 'image'
  ? '✅ Recibí tu imagen. La estoy procesando y te aviso cuando esté lista para revisión.\n\n💡 Si en el pie de foto incluyes el título y el autor, el texto sale mucho mejor.'
  : '🎬 Recibí tu video. Por ahora solo proceso imágenes: el video queda guardado hasta que esté disponible.';
try { await tg('sendMessage', { chat_id: e.chat_id, text, ...(e.message_id ? { reply_to_message_id: e.message_id, allow_sending_without_reply: true } : {}) }); } catch (err) { /* no bloquea */ }
return [{ json: e }];

const tg = (method, body) => this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/${method}`, body, json: true, timeout: 30000 });
// Cuenta al remitente cómo terminó WF20. Los fallos de Gemini que se reintentan solos no se presentan como error
const r = $input.first().json;
const e = $('Crear item y paso').first().json;
const ok = r.ok === true && r.status === 'ready_for_review';
const text = ok ? '✅ Tu pieza quedó lista para revisión.' : '⚠️ No terminé de procesar tu pieza. El administrador ya tiene el aviso y se reintenta si fue un problema temporal.';
try { await tg('sendMessage', { chat_id: e.chat_id, text }); } catch (err) { /* no bloquea */ }
return [{ json: { ok: r.ok === true, content_item_id: e.content_item_id, status: r.status ?? null, error_type: r.error_type ?? null } }];

// El video queda en 'ingested' hasta la Fase 6
const e = $input.first().json;
return [{ json: { ok: true, content_item_id: e.content_item_id, status: 'ingested', waiting_video: true } }];

const tg = (method, body) => this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/${method}`, body, json: true, timeout: 30000 });
// Cualquier excepción de la ingesta: item en 'error' si ya existe, fila en error_log y aviso al administrador y al remitente
const raw = $input.first().json;
const mask = (s) => String(s).replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***');
const message = mask(raw.error?.message ?? raw.error ?? raw.message ?? 'Error sin mensaje').slice(0, 2000);
const error_type = (message.match(/^([a-z_]+):/) ?? [])[1] ?? 'execution_error';
const entrada = $('Entrada').first(0, 0)?.json ?? {};
const itemId = $('Crear item y paso').isExecuted ? ($('Crear item y paso').first(0, 0)?.json?.content_item_id ?? null) : null;
const base = `${$env.SUPABASE_URL}/rest/v1`;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json', Prefer: 'return=minimal' };
const attempt = async (fn) => { try { await fn(); return true; } catch (err) { return false; } };
if (itemId) await attempt(() => this.helpers.httpRequest({ method: 'PATCH', url: `${base}/content_items?id=eq.${itemId}`, headers, json: true, body: { status: 'error' }, timeout: 30000 }));
const logged = await attempt(() => this.helpers.httpRequest({ method: 'POST', url: `${base}/error_log`, headers, json: true, timeout: 30000,
  body: { workflow: '30-recibir-pieza', content_item_id: itemId, error_type, error_message: message } }));
await attempt(() => tg('sendMessage', { chat_id: $env.TELEGRAM_ADMIN_CHAT_ID, text: `⚠️ 30 - Recibir pieza: ${message.slice(0, 500)}\nEjecución: ${$execution.id}` }));
if (/^-?\d{1,20}$/.test(String(entrada.chat_id ?? ''))) await attempt(() => tg('sendMessage', { chat_id: entrada.chat_id, text: '⚠️ No pude recibir tu archivo. Ya avisé al administrador.' }));
return [{ json: { ok: false, error_type, error_message: message, content_item_id: itemId, logged } }];
